return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Indonesian','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-06 21:23+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'id_ID','plural-forms'=>'nplurals=1; plural=0;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" disimpan.','"%1$s" created. %2$d template updated.'=>'"%1$s" dibuat. %2$d template diperbarui.' . "\0" . '','"%s" created.'=>'"%s" dibuat.','"product" (replaces "article")'=>'"produk" (mengganti "artikel")','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d karakter — baik, sedikit di atas batas ideal %2$d tetapi masih dalam rentang %3$d karakter yang diterima. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d karakter — panjang ideal. %2$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d karakter — kemungkinan terpotong di SERP (pertahankan di bawah %2$d). %3$s','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d karakter — terlalu pendek (targetkan %2$d–%3$d). %4$s','%1$d internal, %2$d external.'=>'%1$d internal, %2$d eksternal.','%1$d of %2$d image(s) missing alt text.'=>'%1$d dari %2$d gambar tidak memiliki teks alt.','%1$d words — below recommended minimum of %2$d.'=>'%1$d kata — di bawah minimum yang disarankan yaitu %2$d.','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d kata — konten sangat tipis. Pertimbangkan untuk memperluas hingga setidaknya %2$d kata.','%d chars — good length.'=>'%d karakter — panjang yang baik.','%d external link(s), no internal links.'=>'%d tautan eksternal, tanpa tautan internal.','%d external link(s), no internal links. Add internal links to related content.'=>'%d tautan eksternal, tidak ada tautan internal. Tambahkan tautan internal ke konten terkait.','%d H1 tags found — a page should have exactly one H1.'=>'%d tag H1 ditemukan — sebuah halaman harus memiliki tepat satu H1.','%d image(s), all have alt text.'=>'%d gambar, semuanya memiliki teks alt.','%d language not yet linked'=>'%d bahasa belum terhubung' . "\0" . '','%d link updated.'=>'%d tautan diperbarui.' . "\0" . '','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'%d file locale tidak dapat dihapus secara otomatis (DISALLOW_FILE_MODS disetel). Hapus secara manual melalui server Anda atau WP-CLI: wp language core uninstall <locale>.' . "\0" . '','%d locale file removed.'=>'%d file locale dihapus.' . "\0" . '','%d locale pack installed.'=>'%d paket lokal terpasang.' . "\0" . '','%d navigation reference updated.'=>'%d referensi navigasi diperbarui.' . "\0" . '','%d part reference updated.'=>'%d referensi bagian diperbarui.' . "\0" . '','%d words.'=>'%d kata.','%s Archive'=>' Arsip %s','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s aktif dan sudah menghasilkan JSON-LD Schema.org. Lingua Forge telah menonaktifkan output skema sendiri untuk mencegah grafik yang bertentangan. Tidak seperti Open Graph — di mana LF menambahkan og:locale di atas output plugin lain — skema tidak dapat dilengkapi secara bersih: grafik JSON-LD duplikat atau tumpang tindih menghasilkan kesalahan validasi. Nonaktifkan output skema di plugin yang terdeteksi jika Anda ingin LF menangani data terstruktur.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s aktif dan menghasilkan sitemap sendiri. Sitemap tersebut terpisah dari LF. Keduanya harus diserahkan ke Google Search Console: sitemap plugin SEO mencantumkan konten Anda; sitemap LF menambahkan tautan alternatif multibahasa. Sitemap LF diumumkan secara otomatis di robots.txt.','(avg %.1f hits/block)'=>'(rata-rata %.1f keberhasilan/blok)','(avg %.1f hits/entry)'=>'(rata-rata %.1f hits/entri)','(disabled)'=>'(dinonaktifkan)','(no title) #%d'=>'(tanpa judul) #%d','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} tidak memiliki tautan yang dapat diganti — lakukan pemindaian ulang untuk menyelidiki)','.txt file(s) in the directory'=>'.txt file(s) di direktori','/ 100'=>'/ 100','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1 H1 ✓ — tidak ada subjudul H2 (dapat diterima untuk jenis konten ini).','1 H1 ✓ — no H2 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — tidak ditemukan subjudul H2. Menambahkan H2 meningkatkan struktur.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d template yang dilokalisasi dari tema &#8220;%2$s&#8221; disimpan di database tetapi saat ini tidak aktif. Mereka akan aktif kembali jika Anda mengaktifkan kembali tema tersebut. Untuk membawa terjemahan Anda ke tema baru, regenerasi melalui <strong>Pengaturan → Lingua Forge → Router → FSE scaffold</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> tautan yang dapat diperbaiki otomatis','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> tautan yang membutuhkan tinjauan manual','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> jalur usang','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> masalah template','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'File robots.txt fisik ada di root situs. WordPress\'s virtual robots.txt — dan Sitemap: filter LF — dilewati. Sitemap LF tidak diumumkan ke mesin pencari.','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Hanya menerima file .mo yang dikompilasi. Nama file harus mengikuti pola {textdomain}-{locale}.mo. Mengunggah file dengan nama yang sama dengan yang sudah ada akan menggantinya.','Action'=>'Tindakan','Actions'=>'Tindakan','active'=>'aktif','Active Languages'=>'Bahasa Aktif','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Bahasa aktif: tambahkan setiap bahasa yang ingin Anda dukung. Setiap bahasa mendapatkan awalan URL atau subdomain dan tag hreflang di bagian &lt;head&gt; halaman.','Active Provider'=>'Penyedia Aktif','Add entry'=>'Tambah entri','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Tambahkan instruksi untuk meningkatkan draf — misalnya buat lebih singkat, tambahkan bagian kesimpulan, gunakan register yang lebih formal, sertakan blok FAQ…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Tambahkan instruksi untuk meningkatkan draf — misalnya buat lebih singkat, tambahkan bagian kesimpulan, gunakan register yang lebih formal…','Add new entry'=>'Tambah entri baru','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Tambahkan satu istilah per baris. Baik istilah sumber maupun tampilan target diperlukan. Pasangan bahasa menentukan pekerjaan terjemahan mana yang berlaku untuk batasan ini.','Add Sitemap directive to robots.txt'=>'Tambahkan direktif Sitemap ke robots.txt','Add the following line to your robots.txt manually:'=>'Tambahkan baris berikut ke robots.txt secara manual:','Add WooCommerce product tags to Open Graph output'=>'Tambahkan tag produk WooCommerce ke output Open Graph','Adds a link to the home page so visitors can browse in their language.'=>'Menambahkan tautan ke halaman beranda agar pengunjung dapat menjelajah dalam bahasa mereka.','Administrators only (manage_options)'=>'Hanya administrator (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Setelah mengubah bahasa utama, bersihkan permalink (bagian di bawah) agar pengaturan URL diperbarui.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Setelah mengubah pengaturan struktur URL (awalan jalur ↔ subdomain), selalu kunjungi Pengaturan → Tautan Permanen dan klik Simpan Perubahan untuk membersihkan aturan penulisan ulang.','AI analysis failed. Please try again.'=>'Analisis AI gagal. Silakan coba lagi.','AI Behaviour Preset'=>'Preset Perilaku AI','AI cache cleared. %d entry was removed.'=>'Cache AI dibersihkan. %d entri dihapus.' . "\0" . '','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'Cache AI: daftar respons AI yang di-cache dengan jumlah hit. Bersihkan seluruh cache atau entri posting tunggal. Gunakan "Bersihkan" sebelum menguji perubahan terjemahan — hasil yang di-cache akan dikembalikan bahkan saat Anda mengubah preset AI atau model sampai entri cache dikeluarkan.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Fitur AI bersifat opsional. Pengaturan routing bahasa, hreflang, switcher bahasa, dan sistem grup terjemahan semuanya berfungsi tanpa penyedia yang dikonfigurasi.','AI Limits & Security'=>'Batas & Keamanan AI','AI provider returned an empty response.'=>' Penyedia AI mengembalikan respons kosong.','AI Recommendations'=>'Rekomendasi AI','AI returned an unexpected response format. Please try again.'=>'AI mengembalikan format respons yang tidak terduga. Silakan coba lagi.','AI Usage'=>'Penggunaan AI','AI Usage & Cache'=>'Penggunaan & Cache AI','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Targetkan 120–160 karakter. Biarkan kosong untuk menggunakan fallback kutipan.','All major search engines — Google, Bing, and Yandex — discover the sitemap automatically via the Sitemap: directive in robots.txt. No manual action is required. The buttons below send an immediate ping so the engine recrawls the sitemap now rather than waiting for its next scheduled robots.txt check.'=>'Semua mesin pencari utama — Google, Bing, dan Yandex — secara otomatis menemukan sitemap melalui direktif Sitemap: di robots.txt. Tidak diperlukan tindakan manual. Tombol di bawah mengirim ping langsung agar mesin pencari mengindeks ulang sitemap sekarang daripada menunggu pemeriksaan robots.txt berikutnya.','All time'=>'Semua waktu','All types'=>'Semua jenis','Allow editors to lock individual blocks'=>'Izinkan editor mengunci blok individual','Allow Gutenberg template-editing mode on post screens'=>'Izinkan mode pengeditan template Gutenberg di layar posting','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Juga hapus penugasan bahasa, hubungan terjemahan, meta deskripsi, glosarium, dan Memori Terjemahan saat plugin dihapus','Also generate meta description'=>'Juga buat deskripsi meta','Alternative (server-side):'=>'Alternatif (sisi server):','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Selalu keluarkan hanya og:locale dan og:locale:alternate. Gunakan saat plugin atau tema lain menangani set OG lengkap.','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Selalu keluarkan set OG + Twitter Card lengkap terlepas dari plugin lain. Gunakan hanya jika tidak ada plugin lain yang mengeluarkan tag OG.','An unknown error occurred.'=>'Terjadi kesalahan yang tidak diketahui.','Analyse…'=>'Analisis…','Analysis'=>'Analisis','Analysis request failed. Please try again.'=>'Permintaan analisis gagal. Silakan coba lagi.','Analyzing…'=>'Menganalisis…','and'=>'dan','Anthropic (Claude)'=>'Anthropic (Claude)','any'=>'apa saja','API calls saved by cache'=>'Panggilan API yang disimpan oleh cache','API Key'=>'Kunci API','API Keys'=>'Kunci API','API Keys Tab'=>'Tab Kunci API','API Response Cache'=>'Cache Respons API','Appends the following line to your existing robots.txt: %s'=>'Menambahkan baris berikut ke robots.txt Anda yang ada: %s','Applied ✓'=>'Tersimpan ✓','Apply failed — please try again.'=>'Gagal menerapkan — silakan coba lagi.','Apply to Block'=>'Terapkan ke Blok','Apply to Editor'=>'Terapkan ke Editor','Apply to Footnote'=>'Terapkan ke Catatan Kaki','Apply to Meta Description'=>'Terapkan ke Deskripsi Meta','Apply translation'=>'Terapkan terjemahan','Applying…'=>'Sedang menerapkan…','Approximate size'=>'Ukuran perkiraan','Archive'=>' Arsip','Archive: %s'=>' Arsip: %s','Article / WebPage'=>'Artikel / Halaman Web','Article / WebPage — all singular posts and pages'=>'Artikel / Halaman Web — semua posting dan halaman tunggal','Authors and above (edit_published_posts)'=>'Penulis dan di atasnya (edit_published_posts)','Auto (recommended)'=>'Auto (direkomendasikan)','Behavior'=>'Perilaku','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Perilaku: pilih preset AI (Literal, Balanced, Creative), tambahkan instruksi prompt khusus situs, aktifkan atau nonaktifkan terjemahan otomatis setelah menyimpan posting, dan konfigurasikan Memori Terjemahan.','Block Content'=>'Konten Blok','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Menampilkan pemberitahuan sopan saat halaman saat ini ditampilkan dalam bahasa sumbernya karena tidak ada terjemahan untuk bahasa pengunjung. Dikendalikan oleh sinyal LINGUAFORGE_LANG_FALLBACK_ACTIVE dari router Lingua Forge — tidak mengeluarkan apa pun saat terjemahan ada untuk lokal permintaan.','Block Editor'=>'Editor Blok','block keywordfallback'=>'fallback','block keywordi18n'=>'i18n','block keywordlanguage'=>'bahasa','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'terjemahan','Block locking'=>'Mengunci blok','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Polanya terdaftar untuk tipe pos khusus. Gunakan tombol Terjemahkan untuk menghasilkan varian bahasa. Konten yang diterjemahkan disimpan di sini dan dapat disalin ke pos CPT apa pun dari penyisip pola editor blok atau digunakan sebagai titik awal untuk Pola Sinkron (Blok yang Dapat Digunakan Kembali).','block titleMissing Translation Notice'=>'Pemberitahuan Terjemahan Hilang','Block translation reuses'=>'Penggunaan ulang terjemahan blok','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'Cache terjemahan tingkat blok yang dibagikan antar posting. Ketika diaktifkan, blok identik (markup yang sama, pasangan bahasa, dan glosarium) disajikan dari memori alih-alih memanggil AI lagi. Konfigurasi di Pengaturan → Perilaku.','Blog / Editorial'=>'Blog / Editorial','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Posting blog menggunakan Artikel; semua jenis posting lain dan halaman menggunakan WebPage. Termasuk judul, deskripsi, inLanguage, url, datePublished, dateModified, gambar, dan penerbit.','Browser language redirect'=>'Pengalihan bahasa browser','Built-in preset instructions:'=>'Instruksi preset bawaan:','Bulletize (•-prefixed)'=>'Buat poin-poin (diawali •)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Cache padanan terjemahan di tingkat blok agar konten yang dapat digunakan kembali (footer bersama, sidebar, akordeon, bagian hukum yang banyak boilerplate) tidak memanggil API setiap kali. Saat diaktifkan, alur terjemahan mem-parsing setiap posting ke dalam blok, mencari setiap blok di cache, dan hanya mengirim blok yang tidak di-cache ke AI dalam satu permintaan batch. Suntingan glosarium dan perubahan preset Kepatuhan secara otomatis membatalkan cache terjemahan yang terpengaruh. Lihat statistik dan bersihkan cache di bawah Pemeliharaan.','cached'=>'disimpan sementara','Cached API responses'=>'Respons API yang di-cache','Cached block translations'=>'Terjemahan blok yang di-cache','Cancel'=>'Batal','Cannot determine target language from slug.'=>' Tidak dapat menentukan bahasa target dari slug.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'Tidak dapat menulis ke produk %1$d: ini adalah versi terjemahan (bahasa: %2$s)%3$s. Data operasional (harga, stok, SKU, dimensi) harus diperbarui pada produk sumber. Selesaikan ID produk sumber melalui: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Canonical tag'=>'Tag Kanonik','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Batasi penggunaan AI yang dapat dihasilkan situs dan batasi peran pengguna yang dapat memicu panggilan AI berbayar. Terletak di atas batas laju per pengguna (30 permintaan / menit, dikodekan keras) yang sudah melindungi terhadap loop liar pengguna tunggal.','chars'=>'karakter','Chunk translated'=>'Potongan yang diterjemahkan','Chunk translated to:'=>'Potongan yang diterjemahkan ke:','Clear'=>'Hapus','Clear All'=>'Hapus Semua','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Bersihkan semua hasil AI yang di-cache? Permintaan di masa depan akan memicu panggilan API baru sampai cache dibangun kembali.','Clear API Response Cache'=>'Hapus Cache Respons API','Clear Debug Files'=>'Hapus File Debug','Clear hints'=>'Hapus petunjuk','Clear input'=>'Hapus input','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Hapus seluruh Memori Terjemahan? Terjemahan di masa depan akan membangun kembali cache saat mereka berjalan.','Clear Translation Memory'=>'Hapus Memori Terjemahan','Close'=>'Tutup','Close language panel'=>'Tutup panel bahasa','Close popover'=>'Tutup popover','Compatibility'=>'Kesesuaian','Compliance Preset'=>'Preset Kepatuhan','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Konfigurasikan penyedia AI di Pengaturan → API Keys untuk mengaktifkan rekomendasi berbasis AI.','Content generated'=>'Konten yang dibuat','Content Generator'=>'Generator Konten','Content ready'=>'Konten siap','Contributors and above — default (edit_posts)'=>'Kontributor dan di atasnya — default (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Kontrol berapa banyak konten yang dikirim ke AI dan seberapa besar respons yang dapat diberikan. Tinggalkan bidang kosong untuk menggunakan default bawaan (ditampilkan sebagai placeholder). Tingkatkan nilai ini jika halaman besar terpotong; turunkan untuk mengurangi biaya API.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Mengontrol anggaran token dan batas input untuk fitur Generator Konten AI. Biarkan bidang kosong untuk menggunakan default bawaan.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Mengontrol apa yang terjadi ketika administrator menghapus plugin dari Plugins → Installed Plugins → Delete. Pengaturan plugin dan cache AI selalu dihapus. Penugasan bahasa dan hubungan terjemahan secara default dipertahankan sehingga penghapusan tidak sengaja atau pemasangan ulang dapat melanjutkan dari tempat terakhir.','Conversational'=>' Percakapan','Copied ✓'=>'Disalin ✓','Copy'=>'Salin','Copy failed — please copy the URL manually.'=>'Gagal menyalin — silakan salin URL secara manual.','Copy markup'=>'Salin markup','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Salin URL saat ini ke clipboard. Menampilkan toast "Tautan disalin" saat berhasil.','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Salin hasilnya dan tempelkan di mana pun diperlukan (misalnya langsung ke bidang catatan kaki).','Copy to safe storage'=>'Salin ke penyimpanan aman','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'aksi JS copy/native/auto: ditangani oleh social-share.js LF','Could not add entry: source term and target term are required.'=>'Tidak dapat menambahkan entri: istilah sumber dan istilah target diperlukan.','Could not copy the file. Check that the uploads folder is writable.'=>'Tidak dapat menyalin file. Periksa apakah folder unggahan dapat ditulis.','Could not instantiate the provider.'=>'Tidak dapat menginisialisasi penyedia.','Could not save the file. Check that the uploads folder is writable.'=>'Tidak dapat menyimpan file. Periksa apakah folder unggahan dapat ditulis.','Could not save the glossary entry.'=>'Tidak dapat menyimpan entri glosarium.','Could not write to robots.txt. Check file permissions.'=>'Tidak dapat menulis ke robots.txt. Periksa izin file.','CPT Block Patterns'=>'Polanya Blok CPT','Create'=>'Buat','Create missing'=>'Buat yang hilang','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Membuat terjemahan untuk tipe pos "%s" memerlukan integrasi aktif. Pastikan integrasi yang diperlukan terpasang dan aktif.','Creating…'=>'Sedang membuat…','Creative / Marketing'=>'Kreatif / Pemasaran','Creative / Marketing instructions'=>'Instruksi Kreatif / Pemasaran','Current content (will be overwritten)'=>'Isi saat ini (akan ditimpa)','Current status'=>'Status saat ini','Current title'=>'Judul saat ini','Current: {current}'=>'Saat ini: {current}','Currently emitting'=>'Sedang mengeluarkan','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Saat ini diwarisi dari konstanta %s. Memilih nilai di sini akan mengesampinginya.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Saat ini dilewati untuk posting yang menggunakan placeholder atribut komentar blok (wp:details bidang ringkasan, dll.) — mereka akan melewati jalur terjemahan panggilan tunggal yang ada.','Currently:'=>'Saat ini:','Custom'=>'Kustom','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Kuota AI harian tercapai (%1$d permintaan). Reset pada %2$s UTC.','Daily request limit'=>'Batas permintaan harian','Danger Zone'=>'Zona Bahaya','Debug Files'=>'File Debug','Debug files cleared. %d file was removed.'=>'File debug dibersihkan. %d file dihapus.' . "\0" . '','Debug logging'=>'Pencatatan debug','Debug logging disabled.'=>'Pencatatan debug dinonaktifkan.','Debug logging enabled.'=>'Pencatatan debug diaktifkan.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Debug: aktifkan log debug untuk menangkap prompt AI dan respons API ke file lokal. Nonaktifkan setelah pemecahan masalah — mode debug menulis file pada setiap permintaan AI.','Default OG image'=>'Gambar OG default','Delete'=>'Hapus','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Hapus semua file .txt di direktori debug? Direktori itu sendiri akan tetap ada sehingga penulisan debug di masa depan tetap bersih.','Delete all files for this override (both .mo and .po)?'=>'Hapus semua file untuk penimpa ini (baik .mo maupun .po)?','Delete content data on uninstall'=>'Hapus data konten saat uninstall','Delete this glossary entry?'=>'Hapus entri glosarium ini?','Describe what to write — topic, key points, structure…'=>'Jelaskan apa yang harus ditulis — topik, poin utama, struktur…','Details ↗'=>'Detail ↗','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Deteksi plugin SEO aktif (Yoast, Rank Math, dll.) saat runtime. Hanya keluarkan og:locale + og:locale:alternate ketika plugin lain sudah menghasilkan set OG lengkap; keluarkan set lengkap saat tidak ada yang terdeteksi.','Directory'=>'Direktori','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'Nonaktifkan selama penyesuaian prompt atau saat Anda membutuhkan setiap permintaan mencapai penyedia AI. Menonaktifkan tidak menghapus entri yang di-cache — mengaktifkannya kembali memulihkannya. Meningkatkan pengeluaran API secara langsung di situs yang sibuk diharapkan saat dinonaktifkan.','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Nonaktifkan hanya untuk situs headless atau implementasi hreflang yang sepenuhnya kustom. Saat dinonaktifkan, LF tidak lagi menghapus tag kanonik inti WordPress dan tidak lagi menekan output hreflang plugin SEO.','Disabled'=>'Dinonaktifkan','Disabled (by setting)'=>'Dinonaktifkan (dengan pengaturan)','Disabled (mode setting)'=>'Dinonaktifkan (pengaturan mode)','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Dinonaktifkan karena plugin mu lf-social-share sudah menyediakan fitur ini.','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS disetel.','Display'=>'Tampilan','Displays the Lingua Forge language switcher.'=>'Menampilkan pengalih bahasa Lingua Forge.','Do not output any OG tags.'=>'Jangan keluarkan tag OG apa pun.','Documentation'=>'Dokumentasi','Done'=>'Selesai','Done — {done} of {total} post(s) fixed.'=>'Selesai — {done} dari {total} posting diperbaiki.','Down'=>'Bawah','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Unduh dan pasang paket bahasa inti WordPress langsung dari WordPress.org. Setelah terpasang, locale menjadi tersedia untuk routing URL dan alur kerja terjemahan AI. Daftar bahasa yang tersedia diambil sesuai permintaan — klik tombol di bawah untuk memuatnya.','Dropdown direction'=>'Arah dropdown','edit'=>'sunting','Editors and above (edit_others_posts)'=>'Editor dan di atasnya (edit_others_posts)','Enable API response caching'=>'Aktifkan caching respons API','Enable block-level translation cache reuse across posts'=>'Aktifkan penggunaan kembali cache terjemahan tingkat blok di seluruh posting','Enable Social Share URL rewriting for Social Icons blocks'=>'Aktifkan penulisan ulang URL Share Sosial untuk blok Ikon Sosial','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'Aktifkan saat tema Anda menampilkan judul posting sebagai H2 bukan H1 (umum di beberapa tema blok). Analisis ini mengambil halaman yang dirender dan, jika tidak menemukan H1 tetapi menemukan H2, akan mempromosikan H2 pertama menjadi H1 untuk penilaian.','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Masukkan kunci API Anda untuk setidaknya satu penyedia AI. Kunci dienkripsi saat istirahat menggunakan AES-256-GCM dengan rahasia khusus situs (LINGUAFORGE_SECRET). Jangan bagikan ekspor basis data tanpa mengganti rahasia terlebih dahulu.','environment variable'=>'variabel lingkungan','Error'=>'Kesalahan','Expand'=>'Perluas','Expected: {expected}'=>'Diharapkan: {expected}','External share services'=>'Layanan berbagi eksternal','Extra guidance — tone, style, constraints, target audience…'=>'Panduan tambahan — nada, gaya, batasan, audiens target…','Extra guidance — tone, style, constraints…'=>'Panduan tambahan — nada, gaya, batasan…','Failed. Please try again.'=>'Gagal. Silakan coba lagi.','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'URL gambar cadangan digunakan saat halaman tidak memiliki gambar unggulan, logo situs, atau ikon situs. Ditampilkan dalam pratinjau sosial untuk arsip, indeks blog, dan halaman tunggal tanpa thumbnail.','Feature'=>'Fitur','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Fitur dikelompokkan menjadi dua tingkat. Masukkan pengenal model yang tepat untuk setiap tingkat dan penyedia. Tinggalkan bidang kosong untuk menggunakan default bawaan (ditampilkan sebagai placeholder). Hanya model dari penyedia aktif yang dipanggil saat runtime — konfigurasikan yang lain sebelumnya jika Anda berencana beralih.','File copied to safe storage successfully.'=>'File berhasil disalin ke penyimpanan aman.','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Modifikasi file dinonaktifkan (DISALLOW_FILE_MODS).','Files'=>'File','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'File disimpan di direktori di bawah ini. Berguna untuk mendiagnosis masalah terjemahan — matikan setelah Anda mendapatkan apa yang Anda butuhkan agar file tidak menumpuk. Anda juga dapat memaksa ini dari wp-config.php dengan `define( \'LINGUAFORGE_AI_DEBUG\', true );` yang akan menimpa toggle.','Filter'=>'Filter','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Filter berdasarkan bahasa dan jenis posting, telusuri konten Anda, dan klik Analisis pada item apa pun untuk menjalankan audit SEO berbasis aturan — panjang judul, deskripsi meta, jumlah kata, struktur heading, cakupan alt gambar, dan tautan internal.','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filter dengan linguaforge_debug_dir untuk mengarahkan output debug ke lokasi yang tidak publik.','Finding'=>'Penemuan','Fix'=>'Perbaiki','Fix All'=>'Perbaiki Semua','Fix all links'=>'Perbaiki semua tautan','Fix all parts'=>'Perbaiki semua bagian','Fix Links'=>'Perbaiki Tautan','Fix Nav'=>'Perbaiki Navigasi','Fix Parts'=>'Perbaiki Bagian','Fix Template'=>'Perbaiki Template','Fixing {n} / {total}…'=>'Memperbaiki {n} / {total}…','Fixing…'=>'Memperbaiki…','Flush Permalink Rules'=>'Flush Permalink Rules','Flush Permalinks'=>'Flush Permalinks','Flush Sitemap Cache'=>'Flush Cache Peta Situs','Footnote Content'=>'Isi Catatan Kaki','footnote(s) translated — applied together with content.'=>'Catatan kaki yang diterjemahkan — diterapkan bersama konten.','Footnotes'=>'Catatan kaki','Footnotes payload (advanced)'=>'Payload catatan kaki (lanjutan)','Forbidden'=>'Dilarang','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Dipaksa OFF oleh konstanta LINGUAFORGE_AI_DEBUG di wp-config.php. Hapus baris itu untuk mengontrol toggle ini dari sini.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Dipaksa ON oleh konstanta LINGUAFORGE_AI_DEBUG di wp-config.php. Hapus baris itu untuk mengontrol toggle ini dari sini.','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Memaksa peta situs untuk dibuat ulang pada permintaan berikutnya. Gunakan setelah impor massal atau mengedit hubungan terjemahan secara manual.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Ditemukan {parts} di seluruh <strong>{total}</strong> dari <strong>{scanned}</strong> posting yang dipindai untuk <strong>{lang}</strong>.','From'=>'Dari','Front Page'=>' Halaman Depan','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'lokalisasi FSE: buat, terjemahkan, dan perbaiki tautan dalam template dan bagian template Pengeditan Situs Penuh langsung dari tab ini.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Template FSE disemai dari tema aktif. Buat lalu sesuaikan di Editor Situs.','Full'=>'Penuh','Full Article'=>'Artikel Penuh','Full post'=>'Pos lengkap','General'=>'Umum','Generate'=>'Hasilkan','Generate Content'=>'Hasilkan Konten','Generate content…'=>'Hasilkan konten…','Generate Excerpt'=>'Hasilkan Kutipan','Generate Meta Description'=>'Hasilkan Deskripsi Meta','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Hasilkan peta situs multibahasa di /lf-sitemap.xml','Generated Content'=>'Konten yang dihasilkan','Generated meta description'=>'Meta deskripsi yang dihasilkan','Generating…'=>'Sedang menghasilkan…','Generation failed.'=>'Gagal menghasilkan.','Getting started'=>'Memulai','Global AI preset'=>'Preset AI global','Global default (%s)'=>'Default global (%s)','Glossary'=>'Glosarium','Glossary entry added.'=>'Entri glosarium ditambahkan.','Glossary entry removed.'=>'Entri glosarium dihapus.','Glossary Tab'=>'Tab Glosarium','Google (Gemini)'=>'Google (Gemini)','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'Mode H2-sebagai-H1 diaktifkan — judul dihitung sebagai setara H1. (Tag heading tidak dapat dideteksi dari halaman yang dirender; pastikan tema Anda menampilkan judul dengan benar.)','Headings'=>'Judul','Hide'=>'Sembunyikan','Hints'=>'Petunjuk','Home link text'=>'Teks tautan beranda','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Bagaimana seharusnya muncul dalam terjemahan. Ketik nilai yang sama dengan istilah sumber untuk menginstruksikan AI agar mempertahankannya secara verbatim.','How to use'=>'Cara penggunaan','Hreflang'=>'Hreflang','Hreflang output'=>'Output Hreflang','Hreflang settings saved.'=>'Pengaturan Hreflang disimpan.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Ikon + label','Icon only'=>'Hanya ikon','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Jika dicentang, menghapus plugin akan secara permanen menghapus semua penugasan bahasa, hubungan terjemahan, meta deskripsi, preset per halaman, glosarium AI, dan Memori Terjemahan untuk setiap posting di situs ini. Ini tidak dapat dibatalkan. Biarkan tidak dicentang kecuali Anda benar-benar menghapus dukungan multibahasa dari situs.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Jika Anda menginstal plugin SEO umum, panel ini menunjukkan bagaimana LF menyesuaikan untuk menghindari output duplikat. Tujuannya adalah menghindari tabrakan — bukan kerjasama. LF selalu menyediakan lapisan SEO multibahasa (hreflang, og:locale, schema inLanguage) yang memerlukan pengetahuan tentang konfigurasi routing bahasa LF untuk menghasilkan dengan benar.','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Jika Anda menginstal Yoast SEO, Rank Math, All in One SEO, atau SEOPress, Lingua Forge mendeteksinya dan menyesuaikan untuk menghindari output duplikat. Untuk hreflang, LF mengambil alih sepenuhnya dan menekan output plugin karena plugin tersebut tidak dapat menghasilkan hreflang yang benar untuk konfigurasi routing multibahasa. Untuk Open Graph, LF hanya menambahkan og:locale dan og:locale:alternate — sinyal multibahasa yang tidak dapat disediakan plugin — dan meninggalkan set OG dasar ke plugin. Untuk Schema.org, LF menonaktifkan outputnya sendiri sepenuhnya untuk menghindari konflik grafik JSON-LD.','Images'=>'Gambar','Improve writing'=>'Perbaiki penulisan','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'Dalam editor blok, tambahkan blok Ikon Sosial. Untuk setiap ikon, buka pengaturan tautan dan masukkan salah satu nilai "share:" di bawah sebagai URL. Di frontend, LF menggantinya dengan URL berbagi yang benar untuk halaman saat ini.','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Termasuk nama, deskripsi, inLanguage, url, gambar, dan Penawaran dengan harga, mata uang harga, dan ketersediaan. Harga dan ketersediaan berasal dari produk bahasa sumber (model stok bersama).','Includes site name, url, and inLanguage.'=>'Termasuk nama situs, url, dan inLanguage.','Informative'=>' Informatif','Input tokens'=>'Token input','Install'=>'Pasang','Install a Language'=>'Pasang Bahasa','Installed SEO plugins'=>'Plugin SEO yang terpasang','Installing…'=>'Menginstal…','instock / oos / pending from WC stock status'=>'stoks / habis / menunggu dari status stok WC','Instructions (optional)'=>'Instruksi (opsional)','Instructions / key points'=>'Instruksi / poin utama','Integration API'=>'API Integrasi','Internal Link Fixer'=>'Perbaikan Tautan Internal','Introduction only'=>'Hanya pengantar','Invalid file reference.'=>'Referensi file tidak valid.','Invalid filename.'=>'Nama file tidak valid.','Invalid language code.'=>'Kode bahasa tidak valid.','Invalid language.'=>'Bahasa tidak valid.','Invalid locale code.'=>'Kode locale tidak valid.','Invalid or primary language.'=>' Bahasa tidak valid atau utama.','Invalid post ID.'=>'ID posting tidak valid.','Invalid post type.'=>' Jenis posting tidak valid.','Invalid template part.'=>' Bagian template tidak valid.','Invalid template type.'=>' Jenis template tidak valid.','JavaScript-powered actions'=>'Tindakan berbasis JavaScript','Key points, ideas, or structure to build from…'=>'Poin utama, ide, atau struktur untuk dibangun…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Kunci API dienkripsi dengan AES-256-CBC sebelum disimpan di basis data WordPress. Rahasia enkripsi diambil dari garam otentikasi WordPress Anda (wp-config.php), sehingga kunci teks biasa tidak pernah menyentuh basis data.','Landing / Short-form'=>'Landing / Format Singkat','Language'=>'Bahasa','Language %s installed successfully.'=>'Bahasa %s berhasil dipasang.','Language (optional)'=>'Bahasa (opsional)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Pemasangan bahasa dinonaktifkan di server ini (DISALLOW_FILE_MODS diatur).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Pemasangan bahasa dinonaktifkan di server ini. Konstanta DISALLOW_FILE_MODS diatur di wp-config.php. Pasang paket bahasa secara manual melalui WP-CLI: wp language core install de_DE','Language label'=>'Label bahasa','Language Overrides'=>'Penyesuaian Bahasa','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Overriding bahasa: kelola file override .po/.mo khusus untuk string UI Lingua Forge. Gunakan ini daripada mengedit file plugin secara langsung — override tetap ada setelah pembaruan.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Gagal memasang paket bahasa. Bahasa mungkin sudah terpasang, kode locale mungkin salah, atau server Anda memblokir penulisan file.','Language Setup'=>'Pengaturan Bahasa','Language Switcher'=>'Pengalih Bahasa','Language switcher'=>'Switcher bahasa','Language uninstalled. %d post deleted.'=>'Bahasa tidak terpasang. %d posting dihapus.' . "\0" . '','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Salinan khusus bahasa dari bagian template tema. Setelah dibuat, template diperbarui untuk merujuk ke bagian khusus bahasa.','Language:'=>'Bahasa:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Bahasa yang saat ini dikenal oleh router (berasal dari paket lokal WordPress yang terpasang plus bahasa utama). Pasang paket bahasa tambahan di bagian di bawah ini agar lebih banyak bahasa tersedia untuk routing dan terjemahan.','Last 30 days'=>'30 hari terakhir','Last 7 days'=>'7 hari terakhir','Last generated: %s'=>'Terakhir dibuat: %s','Lead paragraph (≤60 w)'=>'Paragraf pembuka (≤60 kata)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Biarkan bidang model kosong untuk menggunakan default bawaan untuk tingkat tersebut. Teks placeholder menunjukkan model mana yang akan digunakan.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Biarkan kosong untuk nama merek dan istilah yang tidak bergantung bahasa yang harus ditegakkan terlepas dari bahasa apa yang kita terjemahkan.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Biarkan kosong untuk menerapkan entri ini ke semua bahasa target — ideal untuk nama merek, singkatan, dan istilah yang harus dipertahankan secara verbatim dalam setiap terjemahan.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Biarkan kosong untuk mempertahankan kunci yang ada. Masukkan nilai baru untuk menggantinya.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Biarkan kosong untuk menggunakan default bawaan. Menghapus override yang disimpan akan mengembalikan ke default saat penyimpanan berikutnya.','Legacy lf-social-share mu-plugin'=>'Plugin mu lf-social-share lama','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Plugin mu lf-social-share lama terdeteksi. LF menunda set OG dasar ke plugin dan hanya mengeluarkan og:locale + og:locale:alternate. Anda dapat menonaktifkan plugin — Social Share bawaan LF (tab SEO → Social Share) dan Open Graph mencakup fungsi yang sama.','Legal / Compliance'=>'Hukum / Kepatuhan','Legal / Compliance instructions'=>'Instruksi Hukum / Kepatuhan','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF selalu menambahkan og:locale dan og:locale:alternate — sinyal OG multibahasa yang tidak dapat diproduksi dengan benar oleh plugin SEO umum. Untuk set OG dasar (og:title, og:description, og:image), LF menghasilkannya saat tidak ada plugin lain. Saat plugin SEO terpasang, LF melewati set dasar untuk menghindari tag duplikat — bukan karena plugin "lebih baik", tetapi karena duplikasi tidak memberikan nilai.','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF menghasilkan peta situs sendiri dengan alternates xhtml:link untuk semua grup terjemahan. Saat plugin SEO terpasang, ia menghasilkan peta situs terpisah — keduanya berdampingan secara independen. Kirimkan keduanya ke Google Search Console: peta situs plugin SEO untuk penemuan konten, peta situs LF untuk sinyal hubungan bahasa.','LF is outputting hreflang tags and has removed the WordPress core canonical tag on multilingual pages.'=>'LF mengeluarkan tag hreflang dan telah menghapus tag kanonik inti WordPress pada halaman multibahasa.','LF is suppressing hreflang output from: %s'=>'LF menekan output hreflang dari: %s','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF menghasilkan hreflang yang akurat untuk setiap bahasa yang dikonfigurasi, termasuk x-default. Plugin SEO umum tidak memiliki akses ke konfigurasi routing LF dan akan menghasilkan hreflang berdasarkan asumsi URL yang salah. LF menekan output mereka melalui filter untuk mencegah tabrakan.','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF menghasilkan JSON-LD multibahasa dengan anotasi inLanguage yang terkait dengan konfigurasi routing bahasanya. Saat plugin SEO terpasang, LF menonaktifkan skema sendiri sepenuhnya: grafik JSON-LD duplikat menghasilkan kesalahan validasi dan tidak ada cara bersih untuk menambah grafik yang ada.','LF provides'=>'LF menyediakan','LF removes the WordPress core canonical tag on multilingual pages because the router\'s language-prefixed rewrite rules and the hreflang x-default are the correct canonical signals for a multilingual site. This prevents a double-canonical if a SEO plugin also outputs one. LF does not add its own canonical — the language routing already makes each URL canonical.'=>'LF menghapus tag kanonik inti WordPress di halaman multibahasa karena aturan penulisan ulang yang diawali bahasa router dan hreflang x-default adalah sinyal kanonik yang benar untuk situs multibahasa. Ini mencegah duplikasi kanonik jika plugin SEO juga menghasilkan satu. LF tidak menambahkan kanonik sendiri — routing bahasa sudah membuat setiap URL menjadi kanonik.','Light'=>'Ringan','Light (default — fast and cost-effective)'=>'Ringan (default — cepat dan hemat biaya)','Light (fast and cost-effective — Haiku / Flash)'=>'Ringan (cepat dan hemat biaya — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Ringan: digunakan untuk deskripsi meta dan pembuatan kutipan — cepat, biaya rendah.','Limit results to pages in the given Lingua Forge language code.'=>'Batasi hasil ke halaman dalam kode bahasa Lingua Forge yang diberikan.','Limits'=>'Batasan','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge menambahkan routing multibahasa, terjemahan berbasis AI, tag SEO hreflang, dan switcher bahasa ke situs WordPress Anda.','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge menambahkan properti Open Graph khusus WooCommerce ke halaman produk sehingga berbagi URL produk di Facebook, Pinterest, dan platform serupa menampilkan jenis produk, harga, dan ketersediaan yang benar.','Lingua Forge AI Tools'=>'Alat AI Lingua Forge','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge memperluas blok Ikon Sosial WordPress Core dengan URL berbagi dinamis. Atur tautan ikon apa pun ke nilai "share:" dan LF akan menulis ulang ke URL berbagi yang benar atau tindakan JavaScript saat render — tidak perlu kode khusus atau plugin pihak ketiga.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge menghasilkan peta situs XML khusus di /lf-sitemap.xml yang menambahkan tautan alternatif bahasa untuk semua konten terjemahan Anda. Peta situs ini melengkapi peta situs inti WordPress dan peta situs plugin SEO apa pun — tidak menggantinya.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge adalah solusi SEO multibahasa lengkap. Tidak diperlukan plugin SEO tambahan.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge adalah solusi SEO multibahasa lengkap. Tidak diperlukan plugin SEO atau plugin peta situs tambahan.','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge menghasilkan tag <link rel="alternate" hreflang> untuk setiap bahasa yang dikonfigurasi di setiap halaman, termasuk x-default yang mengarah ke bahasa sumber. Ini adalah sinyal SEO multibahasa utama untuk Google dan mesin pencari lainnya — tidak diperlukan plugin SEO tambahan.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge menghasilkan meta tag Open Graph dan Twitter Card sehingga URL yang dibagikan menampilkan bahasa, judul, deskripsi, dan gambar yang benar di platform sosial.','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge menghasilkan data terstruktur Schema.org JSON-LD sehingga mesin pencari memahami jenis konten, bahasa, dan metadata Anda. Ini adalah cara utama untuk berkomunikasi dalam anotasi inLanguage untuk konten multibahasa ke Google dan perayap lainnya.','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge membatasi dua fitur Gutenberg secara default untuk menjaga konsistensi perilaku editorial di berbagai bahasa. Pilih di sini jika Anda membutuhkan kemampuan Gutenberg / FSE penuh.','Lingua Forge Settings'=>'Pengaturan Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge menggunakan dua lapisan cache independen untuk menghindari panggilan API AI yang berulang. Gunakan tab di bawah untuk memeriksa dan mengelola masing-masing.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge menggunakan dua tingkat model per penyedia:','Lingua Forge — Quick Translate'=>'Lingua Forge — Terjemahan Cepat','Lingua Forge — Settings'=>'Lingua Forge — Pengaturan','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Modul Share Sosial bawaan Lingua Forge dan Open Graph mencakup semua fungsi yang disediakan oleh mu-plugin, plus dukungan og:locale multibahasa. Anda dapat menonaktifkan mu-plugin dengan aman.','Link copied'=>'Tautan disalin','link(s)'=>'tautan','Links'=>'Tautan','Load available languages'=>'Muat bahasa yang tersedia','Load content'=>'Memuat konten','Loaded from cache.'=>'Dimuat dari cache.','Loading…'=>'Memuat…','Locale only'=>'Hanya lokal','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Terkunci — plugin SEO yang bertentangan aktif. Lihat pemberitahuan di atas.','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate menyimpan terjemahan khususnya di wp-content/languages/loco/ — lokasi yang dapat dihapus secara diam-diam oleh pembaruan inti WP, pemasangan ulang plugin, atau jika Loco Translate sendiri dihapus. Menyalin file di sini memindahkan mereka ke direktori Lingua Forge i18n-overrides, yang tetap ada melalui semua kejadian tersebut dan dimuat secara otomatis setiap permintaan.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Salin ke Penyimpanan Aman','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Kemampuan WordPress terendah yang diizinkan untuk memicu fitur AI. Memperketat ini di situs multi-penulis mencegah Kontributor atau akun percobaan menjalankan panggilan AI berbayar. Override per fitur melalui filter linguaforge_required_capability.','Maintenance'=>'Pemeliharaan','Maintenance Tab'=>'Tab Pemeliharaan','Make casual'=>'Buat santai','Make concise'=>'Buat ringkas','Make formal'=>'Buat formal','Mark citations needed'=>'Tandai kutipan yang diperlukan','Max context characters'=>'Jumlah karakter konteks maksimum','Max hints characters'=>'Jumlah karakter petunjuk maksimum','Max input characters'=>'Karakter input maksimum','Max output tokens'=>'Token output maksimum','Maximum characters accepted from the input field. Default: 8 000.'=>'Jumlah karakter maksimum yang diterima dari bidang input. Default: 8.000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Jumlah karakter konten posting yang ada yang diteruskan ke AI sebagai konteks benih saat tidak ada Petunjuk yang disediakan. Default: 6.000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Jumlah karakter maksimum yang dibaca dari bidang Petunjuk. Default: 2.000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Jumlah karakter maksimum dari konten posting yang diteruskan ke AI. 0 berarti tidak ada batas — seluruh konten selalu dikirim (disarankan). Tetapkan nilai non-nol hanya jika penyedia Anda memiliki jendela konteks yang ketat. Peringatan akan ditulis ke log kesalahan PHP setiap kali konten dipangkas.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Jumlah token maksimum yang dapat diproduksi AI dalam satu respons terjemahan. Jika terjemahan dipotong secara diam-diam di akhir, tingkatkan nilai ini. Default: 16.000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Token maksimum yang dapat diproduksi AI per jalannya generasi. Tingkatkan ini jika artikel lengkap terpotong. Default: 8.192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Token maksimum yang dapat diproduksi AI per terjemahan cepat. Default: 2.000.','Meta Description'=>'Meta Deskripsi','Meta description'=>'Meta deskripsi','Meta Description, Excerpt Generator'=>'Meta Deskripsi, Generator Kutipan','Metric'=>'Metrik','Minimum role'=>'Peran minimum','Missing pattern name or language.'=>' Nama pola atau bahasa yang hilang.','Mode'=>'Mode','Model'=>'Model','Model tier'=>'Tingkat model','Models'=>'Model','Models Tab (General)'=>'Tab Model (Umum)','Modified'=>'Diubah','Most recent cached block'=>'Blok cache terbaru','Most recent cached response'=>'Respons cache terbaru','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'Routing multibahasa, SEO multibahasa lengkap (hreflang, Open Graph, Schema.org, sitemap), dan alat konten AI untuk WordPress. Deteksi bahasa, routing URL, terjemahan, pembuatan konten, dan lapisan SEO lengkap — tanpa plugin pendamping.','Name displayed in this language. Leave empty to use the source name.'=>'Nama yang ditampilkan dalam bahasa ini. Biarkan kosong untuk menggunakan nama sumber.','Navigation'=>'Navigasi','Navigation has no content to translate.'=>'Navigasi tidak memiliki konten untuk diterjemahkan.','Navigation not found.'=>'Navigasi tidak ditemukan.','Navigation posts are translated via the Router tab, not this button.'=>'Pos navigasi diterjemahkan melalui tab Router, bukan tombol ini.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Terjemahan navigasi memerlukan penyedia AI aktif. Konfigurasikan kunci API di tab Kunci API.','Navigations'=>'Navigasi','Network error — could not reach the WordPress AJAX endpoint.'=>'Kesalahan jaringan — tidak dapat menghubungi endpoint AJAX WordPress.','No %s version found in this translation group.'=>'Tidak ditemukan versi %s dalam grup terjemahan ini.','No action needed. Google deprecated its sitemap ping endpoint in January 2024 and now discovers sitemaps exclusively via the robots.txt Sitemap: directive — which LF has already configured. Google will pick it up on its next crawl.'=>'Tidak perlu tindakan. Google menonaktifkan endpoint ping sitemap-nya pada Januari 2024 dan sekarang menemukan sitemap secara eksklusif melalui arahan Sitemap di robots.txt — yang sudah dikonfigurasi LF. Google akan mengambilnya saat perayapan berikutnya.','No AI provider configured.'=>' Penyedia AI tidak dikonfigurasi.','No AI provider configured. Add an API key in Settings → API Keys.'=>'Tidak ada penyedia AI yang dikonfigurasi. Tambahkan kunci API di Pengaturan → Kunci API.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Penggunaan AI tidak tercatat dalam jendela yang dipilih (%s). Pilih rentang yang lebih luas di atas.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Penggunaan AI belum tercatat. Setelah editor menjalankan terjemahan, menghasilkan deskripsi meta, atau menggunakan fitur AI lainnya, total akan muncul di sini.','No API key configured for this provider.'=>'Tidak ada kunci API yang dikonfigurasi untuk penyedia ini.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Tidak ada instruksi bawaan — setiap fitur AI menggunakan default yang disesuaikan sendiri. Isi bidang instruksi Kustom di bawah ini untuk menambahkan aturan situs Anda sendiri.','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'Tidak terdeteksi plugin SEO yang bertentangan. Lingua Forge menangani semua output SEO secara independen.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Belum ada file Loco Translate khusus yang ditemukan. Mereka akan muncul di sini setelah Anda menyimpan terjemahan di Loco Translate.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'Tidak terdeteksi plugin OG eksternal. LF menghasilkan set OG + Twitter Card lengkap.','No file was selected.'=>'Tidak ada file yang dipilih.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Tidak ada entri glosarium yang cocok dengan filter saat ini. Bersihkan filter untuk melihat semua entri, atau tambahkan entri baru di bawah.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Belum ada entri glosarium. Tambahkan di bawah untuk mulai menegakkan terminologi dalam terjemahan.','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'Tidak ditemukan H1. Biasanya judul posting adalah H1 — pastikan tema Anda menghasilkannya.','No images found in content.'=>'Tidak ditemukan gambar dalam konten.','No internal links found to update.'=>' Tidak ditemukan tautan internal untuk diperbarui.','No language-specific template parts found to map.'=>' Tidak ditemukan bagian template khusus bahasa untuk dipetakan.','No LF meta description set — using excerpt/content.'=>'Meta deskripsi LF tidak disetel — menggunakan kutipan/isi.','No links found.'=>'Tidak ditemukan tautan.','No links found. Internal links improve crawlability and user navigation.'=>'Tidak ditemukan tautan. Tautan internal meningkatkan crawlability dan navigasi pengguna.','No meta description found. Generate one via the AI meta description feature.'=>'Meta deskripsi tidak ditemukan. Buat satu menggunakan fitur meta deskripsi AI.','No navigation references needed updating.'=>' Tidak diperlukan pembaruan referensi navigasi.','No override files uploaded yet.'=>'Belum ada file penimpa yang diunggah.','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'Tidak ditemukan file robots.txt fisik. WordPress menghasilkannya secara virtual dan arahan Sitemap LF disertakan secara otomatis.','No published posts found for the selected filters.'=>'Tidak ditemukan posting yang dipublikasikan untuk filter yang dipilih.','No response from AI provider. Check your API key and try again.'=>'Tidak ada respons dari penyedia AI. Periksa kunci API Anda dan coba lagi.','No response from provider — check the error log for details.'=>'Tidak ada respons dari penyedia — periksa log error untuk detailnya.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Tidak ada bahasa sekunder yang dikonfigurasi. Pasang paket bahasa di atas untuk mengaktifkan kerangka template.','No source content found to translate.'=>'Tidak ada konten sumber yang ditemukan untuk diterjemahkan.','No source page linked yet.'=>'Belum ada halaman sumber yang terhubung.','No template part references needed updating.'=>' Tidak diperlukan pembaruan referensi bagian template.','No title set.'=>'Judul tidak disetel.','No translated content found. The sitemap will populate once posts have been translated.'=>'Konten terjemahan tidak ditemukan. Peta situs akan terisi setelah posting diterjemahkan.','No translation found — analyzed the source language version.'=>'Tidak ditemukan terjemahan — menganalisis versi bahasa sumber.','No {lang} translation registered (TRID missing)'=>'Belum ada terjemahan {lang} yang terdaftar (TRID hilang)','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Belum dihasilkan. Peta situs dibangun saat kunjungan pertama ke URL peta situs dan disimpan cache selama 24 jam.','Notes'=>'Catatan','Nothing — all types disabled'=>'Tidak ada — semua tipe dinonaktifkan','Notice message'=>'Pesan pemberitahuan','Notice settings'=>'Pengaturan pemberitahuan','Notify search engines'=>'Beritahu mesin pencari','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'Tag OG/Twitter Card: ditangani oleh modul Open Graph LF (SEO → Open Graph & Twitter Cards)','Oldest cached block'=>'Blok cache tertua','Oldest cached response'=>'Respons cache tertua','Only .mo files are accepted.'=>'Hanya file .mo yang diterima.','Open Graph'=>'Open Graph','Open Graph &amp; Twitter Cards'=>'Open Graph &amp; Twitter Cards','Open Graph output'=>'Output Open Graph','Open Graph settings saved.'=>'Pengaturan Open Graph disimpan.','Open Search Console →'=>'Buka Search Console →','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Buka lembar berbagi Web bawaan browser (iOS, Android, beberapa desktop). Kembali ke salinan clipboard jika tidak didukung.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Konteks opsional untuk editor (misalnya "ASIC = Sirkuit Terintegrasi Khusus Aplikasi; pertahankan dalam bahasa Inggris dalam konteks teknis").','Optional. Bing already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Opsional. Bing sudah membaca arahan Sitemap dari robots.txt — ini hanya memicu perayapan ulang segera daripada menunggu pemeriksaan terjadwal berikutnya.','Optional. Yandex already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Opsional. Yandex sudah membaca arahan Sitemap dari robots.txt — ini hanya memicu perayapan ulang segera daripada menunggu pemeriksaan terjadwal berikutnya.','Output'=>'Output','Output Article or WebPage schema on singular posts and pages'=>'Output skema Artikel atau WebPage pada posting dan halaman tunggal','Output hreflang tags in wp_head'=>'Output tag hreflang di wp_head','Output mode'=>'Mode output','Output Open Graph tags in wp_head'=>'Output tag Open Graph di wp_head','Output Product schema on WooCommerce product pages'=>'Output skema Produk di halaman produk WooCommerce','Output Schema.org JSON-LD in wp_head'=>'Output Schema.org JSON-LD di wp_head','Output tokens'=>'Token output','Output WebSite schema on the front page and blog index'=>'Output skema WebSite di halaman depan dan indeks blog','Overall SEO score'=>'Skor SEO keseluruhan','overridden'=>'yang diubah','Override file deleted.'=>'File penimpa dihapus.','Override file uploaded successfully.'=>'File penimpa berhasil diunggah.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Mengganti preset AI untuk Terjemahan dan Pembuatan Konten di halaman ini. Semua fitur lainnya selalu menggunakan preset global.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Mengganti preset AI untuk Terjemahan dan Pembuatan Konten di halaman ini. Instruksi prompt kustom di seluruh situs (Pengaturan → Perilaku) selalu ditambahkan ke setiap permintaan terlepas dari pilihan ini.','Overview'=>'Ikhtisar','Page'=>'Halaman','Part'=>'Bagian','Paste a footnote, sentence, or any snippet here…'=>'Tempelkan catatan kaki, kalimat, atau potongan apa pun di sini…','Paste text, or select text in the editor first…'=>'Tempel teks, atau pilih teks di editor terlebih dahulu…','Paste text, or select text on the page first…'=>'Tempel teks, atau pilih teks di halaman terlebih dahulu…','Paste your API key…'=>'Tempelkan kunci API Anda…','Path prefix — example.com/de/'=>'Prefix path — example.com/de/','Pattern'=>'Pola','Pattern has no content to translate.'=>' Pola tidak memiliki konten untuk diterjemahkan.','Pattern not found.'=>' Pola tidak ditemukan.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>' Pola diterjemahkan dan disimpan. Salin konten ke posting CPT Anda melalui inserter pola editor blok atau gunakan sebagai titik awal untuk Blok yang Dapat Digunakan Kembali.','Pattern translation failed.'=>'Gagal menerjemahkan pola.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Cache per-pos untuk terjemahan yang dihasilkan AI, deskripsi meta, kutipan, dan konten. Selalu aktif — tidak memerlukan saklar terpisah. Entri dihapus otomatis saat konten atau penyedia/model AI berubah.','Permalink rules flushed successfully.'=>'Aturan permalink berhasil dibersihkan.','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Menghapus secara permanen semua template, bagian template, pola, menu navigasi, posting, halaman, tipe posting khusus, produk, dan variasi produk yang terkait dengan bahasa ini. Juga menghapus file paket lokal WordPress sehingga bahasa ini tidak lagi muncul di router. Tindakan ini tidak dapat dibatalkan.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Hapus permanen %s? Ini akan menghapus semua konten terjemahan untuk bahasa ini dan tidak dapat dibatalkan.','Permission denied.'=>' Izin ditolak.','Persuasive'=>' Persuasif','PHP constant'=>'Konstanta PHP','Pin on Pinterest'=>'Pin di Pinterest','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Tandai istilah yang tidak boleh diterjemahkan atau harus selalu ditampilkan dengan cara tertentu (misalnya nama merek, nama produk, akronim). Batasan glosarium disuntikkan ke setiap permintaan terjemahan AI untuk semua fitur: terjemahan posting, deskripsi meta, kutipan, dan terjemahan template FSE.','Ping Bing'=>'Ping Bing','Ping Yandex'=>'Ping Yandex','Plain language'=>'Bahasa sederhana','Please enter some instructions first…'=>'Harap masukkan beberapa instruksi terlebih dahulu…','Please enter some text first…'=>'Harap masukkan beberapa teks terlebih dahulu…','Plugin'=>'Plugin','Post'=>'Posting','Post not found or not published.'=>'Posting tidak ditemukan atau belum dipublikasikan.','Post not found.'=>'Posting tidak ditemukan.','Post on X / Twitter'=>'Posting di X / Twitter','Post Types'=>'Tipe Pos','Prefilled from excerpt. Edit to override.'=>'Diisi dari kutipan. Sunting untuk menimpa.','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Harga dan ketersediaan selalu mencerminkan produk sumber (model stok bersama). Tag hanya akan ditampilkan saat modul Open Graph LF disetel ke "Full" atau mode "Auto" tanpa plugin SEO yang bertentangan terdeteksi.','Primary Language'=>'Bahasa Utama','Primary language'=>'Bahasa utama','Primary language saved.'=>'Bahasa utama disimpan.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Bahasa utama: bahasa di mana konten Anda yang ada ditulis. Semua terjemahan diproduksi dari bahasa ini; mengubahnya tidak memindahkan atau menghapus posting apa pun.','Processing…'=>'Sedang diproses…','Product'=>'Produk','Product / eCommerce'=>'Produk / eCommerce','Product Open Graph'=>'Open Graph Produk','Product — WooCommerce product pages'=>'Produk — halaman produk WooCommerce','Profile'=>'Profil','Provider'=>'Penyedia','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Penyedia tidak mengembalikan teks. Periksa log kesalahan WordPress untuk alasan kegagalan secara rinci.','Quality'=>'Kualitas','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Kualitas (default — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Kualitas (Soneta / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Kualitas: digunakan untuk terjemahan posting dan pembuatan konten — kualitas lebih tinggi, biaya lebih tinggi.','Quick Translate'=>'Terjemahan Cepat','Quick Translation'=>'Terjemahan Cepat','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Terjemahan Cepat digunakan untuk mode potongan/fragmen — potongan pendek diterjemahkan sesuai permintaan dari toolbar, editor, atau popover blok. Menggunakan konfigurasi yang terpisah dan lebih ringan dari terjemahan halaman penuh untuk menjaga respons tetap cepat dan hemat biaya.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Mengaktifkan kembali canLockBlocks Gutenberg. Berguna untuk template editorial yang perlu mencegah kontributor memindahkan atau menghapus blok tertentu.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Mengaktifkan kembali supportsTemplateMode. Inti dari alur kerja Pengeditan Seluruh Situs di mana override template tingkat posting adalah sengaja.','Re-generates and updates the cached result.'=>'Menghasilkan ulang dan memperbarui hasil yang disimpan sementara.','Re-scan'=>'Pindai ulang','Re-scanning…'=>'Memindai ulang…','Re-translate'=>'Terjemahkan ulang','Reading time'=>'Waktu membaca','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Alihkan pengunjung ke bahasa pilihan mereka berdasarkan header Accept-Language browser','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Perbaiki lebih lanjut — misalnya "buat lebih singkat" atau "gunakan nada formal"…','Refine further:'=>'Perbaiki lebih lanjut:','Refinement'=>'Perbaikan','Refinement failed — please try again.'=>'Perbaikan gagal — silakan coba lagi.','Refining…'=>'Sedang memperbaiki…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Mengregenerasi ulang aturan penulisan ulang WordPress sehingga prefiks URL, slug khusus bahasa, dan penulisan ulang arsip semuanya sinkron. Diperlukan setelah mengubah bahasa utama atau menambahkan dukungan bahasa baru.','Remove stored key'=>'Hapus kunci yang disimpan','Report an issue on GitHub'=>'Laporkan masalah di GitHub','Request failed — please try again.'=>'Permintaan gagal — silakan coba lagi.','Request failed.'=>'Permintaan gagal.','Request failed. Check your connection.'=>'Permintaan gagal. Periksa koneksi Anda.','Request failed. Please try again.'=>'Permintaan gagal. Silakan coba lagi.','Requests'=>'Permintaan','Reset'=>'Reset','Result will appear here…'=>'Hasil akan muncul di sini…','Retranslate'=>'Terjemahkan ulang','Retranslating…'=>'Sedang menerjemahkan ulang…','Review carefully — links and slugs not updated.'=>'Periksa dengan cermat — tautan dan slug tidak diperbarui.','Review translation before applying'=>'Tinjau terjemahan sebelum menerapkan','Revise'=>'Revisi','Revision'=>'Revisi','Revision Type'=>'Jenis Revisi','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt diperbarui dengan direktif Sitemap.','Router'=>'Router','Router Tab'=>'Tab Router','Run AI Analysis'=>'Jalankan Analisis AI','Save analysis settings'=>'Simpan pengaturan analisis','Save Debug Setting'=>'Simpan Pengaturan Debug','Save Hreflang Settings'=>'Simpan Pengaturan Hreflang','Save Open Graph Settings'=>'Simpan Pengaturan Open Graph','Save Router Settings'=>'Simpan Pengaturan Router','Save Schema.org Settings'=>'Simpan Pengaturan Schema.org','Save Settings'=>'Simpan Pengaturan','Save Sitemap Settings'=>'Simpan Pengaturan Sitemap','Save Social Share Settings'=>'Simpan Pengaturan Berbagi Sosial','Save the post to persist changes.'=>'Simpan posting untuk mempertahankan perubahan.','Save Uninstall Setting'=>'Simpan Pengaturan Uninstall','Save WooCommerce SEO Settings'=>'Simpan Pengaturan SEO WooCommerce','Saved to the meta description field when you apply.'=>'Disimpan ke bidang meta deskripsi saat Anda menerapkan.','Scan failed: '=>'Gagal memindai: ','Scan request failed. Please try again.'=>'Permintaan pemindaian gagal. Silakan coba lagi.','Scanning posts for broken language links…'=>'Memindai posting untuk tautan bahasa yang rusak…','Schema output deferred.'=>'Output Schema ditangguhkan.','Schema.org'=>'Schema.org','Schema.org JSON-LD'=>'Schema.org JSON-LD','Schema.org output'=>'Output Schema.org','Schema.org settings saved.'=>'Pengaturan Schema.org disimpan.','Search'=>' Cari','Search Console is useful for monitoring indexing and coverage errors, but is not required for discovery.'=>'Search Console berguna untuk memantau kesalahan pengindeksan dan cakupan, tetapi tidak diperlukan untuk penemuan.','Search Results'=>' Hasil Pencarian','Security check failed — file path is not permitted.'=>'Gagal pemeriksaan keamanan — jalur file tidak diizinkan.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Pilih bahasa untuk mengelola template FSE, bagian template, dan menu navigasi.','Select language'=>'Pilih bahasa','Send via Telegram'=>'Kirim melalui Telegram','Send via WhatsApp'=>'Kirim melalui WhatsApp','SEO'=>'SEO','SEO Analysis'=>'Analisis SEO','SEO character-count info'=>'Informasi jumlah karakter SEO','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'Plugin SEO terdeteksi: %s. LF hanya menampilkan og:locale dan og:locale:alternate; plugin yang terdeteksi menangani seluruh set OG.','SEO plugins and conflict avoidance:'=>'Plugin SEO dan pencegahan konflik:','SEO Tab'=>'Tab SEO','Server setup (subdomain)'=>'Pengaturan server (subdomain)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Mengatur perilaku AI default untuk semua fitur di seluruh situs. Postingan individual dapat mengesampinginya untuk Terjemahan dan Pembuatan Konten melalui kotak meta Lingua Forge.','Settings'=>'Pengaturan','Settings saved.'=>'Pengaturan disimpan.','Share on Facebook'=>'Bagikan di Facebook','Share on LinkedIn'=>'Bagikan di LinkedIn','Share on Mastodon'=>'Bagikan di Mastodon','Share via email (mailto:)'=>'Bagikan melalui email (mailto:)','Show home link'=>'Tampilkan tautan beranda','Shown when no translation exists for the visitor\'s language.'=>'Ditampilkan saat tidak ada terjemahan untuk bahasa pengunjung.','Single'=>' Tunggal','Single %s'=>' %s Tunggal','Single: %s'=>' Tunggal: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Batas atas permintaan AI di seluruh situs per hari UTC (menghitung terjemahan Toolbar dan revisi blok). Penghitung direset pada tengah malam UTC. Atur ke 0 untuk menonaktifkan batas.','Sitemap'=>'Peta Situs','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Cache peta situs dibersihkan. Akan dibuat ulang saat kunjungan berikutnya ke URL peta situs.','Sitemap output'=>'Output peta situs','Sitemap settings saved.'=>'Pengaturan peta situs disimpan.','Sitemap URL'=>'URL peta situs','Size'=>'Ukuran','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Bagikan blok Ikon Sosial: URL: ditangani oleh Share Sosial bawaan LF (SEO → Share Sosial)','Social Share'=>'Share Sosial','Social Share settings saved.'=>'Pengaturan Share Sosial disimpan.','Some link fixes failed.'=>'Beberapa perbaikan tautan gagal.','Some nav ref fixes failed.'=>'Beberapa perbaikan referensi navigasi gagal.','Some part fixes failed.'=>'Beberapa perbaikan bagian gagal.','Some parts could not be created.'=>'Beberapa bagian tidak dapat dibuat.','Some templates could not be created.'=>'Beberapa template tidak dapat dibuat.','Some translations failed.'=>'Beberapa terjemahan gagal.','source'=>'sumber','Source file not found.'=>'File sumber tidak ditemukan.','Source lang'=>'Bahasa sumber','Source language'=>'Bahasa sumber','Source term'=>'Istilah sumber','Standard'=>'Standar','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standar menggunakan suhu yang disesuaikan untuk setiap fitur: Terjemahan T=0.2 (tepat), Terjemahan Cepat T=0.4, Pembuat Konten T=0.6 (kreatif). Preset lainnya menerapkan suhu tetap tunggal di semua fitur.','Status'=>'Status','Status / Actions'=>'Status / Tindakan','Storytelling'=>' Bercerita','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Mode pelestarian ketat untuk konten hukum, regulasi, medis, atau teknis. Saat aktif, setiap fitur AI menggunakan suhu sampling rendah dan menambahkan addendum di bawah ke prompt sistemnya — terminologi, nomor artikel, satuan, nama merek, dan bahasa regulasi dipertahankan secara verbatim daripada diparafrasekan.','Structured Outline'=>'Garis besar terstruktur','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Mode subdomain memerlukan server web Anda untuk menunjuk semua subdomain bahasa (misalnya de.example.com) ke instalasi WordPress ini. Setelah beralih mode, bersihkan aturan permalink dan hapus cache apa pun. Jika URL beranda Anda menyertakan www (misalnya www.example.com), gunakan filter lf_base_domain untuk mengatur domain puncak agar subdomain dibangun dengan benar.','Subdomain — de.example.com/'=>'Subdomain — de.example.com/','Submit this URL to Google Search Console alongside your main sitemap.'=>'Kirim URL ini ke Google Search Console bersama peta situs utama Anda.','Submit to Reddit'=>'Kirim ke Reddit','Suggested meta description'=>'Deskripsi meta yang disarankan','Suggested title'=>'Judul yang disarankan','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Penyedia yang didukung: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Hanya satu penyedia yang aktif pada satu waktu. Pilih penyedia aktif di tab Umum.','Suppressed: %s.'=>'Dihilangkan: %s.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, per fitur','Tag'=>'Tag','Tags emitted'=>'Tag yang dikeluarkan','Target lang'=>'Bahasa target','Target Language'=>'Bahasa Target','Target language'=>'Bahasa target','Target term'=>'Istilah target','Target: 140–160 chars for optimal SERP display'=>'Target: 140–160 karakter untuk tampilan SERP yang optimal','Technical'=>' Teknis','Technical / Scientific'=>'Teknis / Ilmiah','Technical / Scientific instructions'=>'Instruksi Teknis / Ilmiah','Template "%s" already exists.'=>'"%s" sudah ada.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Template "{expected}" tidak ada — buat terlebih dahulu di Editor Situs.','Template has no content.'=>' Template tidak memiliki konten.','Template mode'=>'Mode template','Template not found or not stored in the database.'=>' Template tidak ditemukan atau tidak disimpan dalam database.','Template part "%s" already exists.'=>' Bagian template "%s" sudah ada.','Template part has no content.'=>' Bagian template tidak memiliki konten.','Template part not found or not stored in the database.'=>' Bagian template tidak ditemukan atau tidak disimpan dalam database.','Template Parts'=>'Bagian Template','Templates'=>'Template','Test connection'=>'Uji koneksi','Testing…'=>'Sedang pengujian…','Text domain / locale'=>'Domain teks / lokal','Text to translate'=>'Teks untuk diterjemahkan','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'Cache Respons API menyimpan hasil mentah dari setiap permintaan AI — terjemahan, deskripsi meta, kutipan, dan pembuatan konten — berdasarkan hash dari input (konten, pasangan bahasa, penyedia, model). Permintaan berikutnya dengan input yang sama disajikan dari cache tanpa panggilan API. Cache ini berbeda dari Memori Terjemahan: Memori Terjemahan beroperasi di tingkat blok dan dibagikan antar posting; Cache Respons API beroperasi di tingkat fitur dan dikunci per posting.','The editor did not accept the content — please try again.'=>'Editor tidak menerima konten — silakan coba lagi.','The following directive is active in your virtual robots.txt:'=>'Direktif berikut aktif di robots.txt virtual Anda:','The lf-social-share mu-plugin is active.'=>'Plugin mu lf-social-share aktif.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'Plugin mu lf-social-share aktif. Social Share bawaan Lingua Forge tidak aktif — plugin mengelola penulisan ulang URL berbagi dan tindakan JS.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Tier Light menggunakan model cepat yang dikonfigurasi dalam tabel Model di atas (default: Haiku / Flash). Beralih ke Kualitas jika Anda membutuhkan tingkat akurasi terjemahan yang sama seperti mode halaman penuh untuk potongan.','The phrase as it appears in the source text.'=>'Frasa seperti yang muncul dalam teks sumber.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Bahasa utama selalu disajikan di akar situs Anda — tanpa prefix URL dalam mode path, tanpa subdomain bahasa dalam mode subdomain. Semua bahasa lain menggunakan prefix path /lang/ (misalnya example.com/de/) atau subdomain bahasa (misalnya de.example.com), tergantung pengaturan struktur URL di bawah.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'Tab SEO → Kompatibilitas menunjukkan status deteksi langsung dan menjelaskan secara tepat apa yang dilakukan LF untuk setiap area fitur.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'URL berbagi selalu mencerminkan halaman saat ini — tidak perlu entri URL manual. filter linguaforge_social_share_url memungkinkan Anda mengganti URL yang diselesaikan untuk layanan apa pun.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'Peta situs diumumkan secara otomatis di robots.txt. Semua mesin pencari utama — Google, Bing, Yandex — menemukannya dari robots.txt. Tidak diperlukan pengiriman manual.','The source page has no footnotes.'=>'Halaman sumber tidak memiliki catatan kaki.','The upload failed — please try again.'=>'Unggahan gagal — silakan coba lagi.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'Peta situs inti WordPress mencantumkan semua URL konten Anda. Peta situs LF memberi tahu mesin pencari bagaimana versi bahasa saling terkait melalui alternates xhtml:link hreflang. Kirimkan keduanya ke Google Search Console untuk cakupan penuh.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Catatan kaki ini berasal dari halaman sumber dan ditampilkan di sini hanya untuk referensi. Tambahkan ke halaman ini menggunakan editor blok.','This is the source page. Footnotes are edited directly in the block editor.'=>'Ini adalah halaman sumber. Catatan kaki diedit langsung di editor blok.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Kunci ini saat ini disediakan oleh server %s dan tidak dapat dihapus di sini. Masukkan kunci baru di atas untuk menggantinya dengan nilai dari basis data.','This language is protected and cannot be uninstalled.'=>'Bahasa ini dilindungi dan tidak dapat dihapus.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Bahasa ini cocok dengan lokal instance WordPress dan tidak dapat dihapus.','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tip: untuk mengatur ulang model ke default bawaan, hapus isian dan simpan.','Title'=>'Judul','Title is %1$d chars — aim for %2$d–%3$d.'=>'Judul terdiri dari %1$d karakter — targetkan %2$d–%3$d.','Title is %1$d chars — may be truncated in SERPs (aim for %2$d–%3$d).'=>'Judul adalah %1$d karakter — mungkin dipotong di SERP (targetkan %2$d–%3$d).','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Untuk menggunakan rahasia enkripsi khusus (alih-alih nilai wp_salt yang diambil dari), tambahkan ini ke wp-config.php:','Today'=>'Hari ini','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'Konsumsi token diringkas berdasarkan fitur, penyedia, dan model. Dicatat pada setiap panggilan AI yang berhasil; ping Test Connection dikecualikan agar tidak mempengaruhi total.','Tone'=>'Nada','tone'=>'Nada','Tone:'=>'Nada:','Too many AI requests. Please retry in %d seconds.'=>'Permintaan AI terlalu banyak. Silakan coba lagi dalam %d detik.','Total'=>'Total','Total tokens'=>'Total token','Translate'=>'Terjemahkan','Translate / Revise'=>'Terjemahkan / Revisi','Translate / Revise block'=>'Blok terjemahan / Revisi','Translate all'=>'Terjemahkan semua','Translate chunk'=>'Terjemahkan bagian','Translate Content'=>'Terjemahkan Konten','Translate missing'=>'Terjemahan hilang','Translate page…'=>'Terjemahkan halaman…','Translated content'=>'Isi terjemahan','Translated Names'=>'Nama yang Diterjemahkan','Translated title'=>'Judul terjemahan','Translated to:'=>'Diterjemahkan ke:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Diterjemahkan. Tinjau di Editor Situs — tautan internal, URL navigasi, dan slug template tidak diperbarui secara otomatis.','Translating…'=>'Sedang menerjemahkan…','Translation'=>'Terjemahan','Translation Caching'=>'Caching Terjemahan','Translation found but permalink could not be generated'=>'Terjemahan ditemukan tetapi permalink tidak dapat dibuat','Translation Limits'=>'Batasan Terjemahan','Translation Limits & Behavior'=>'Batas & Perilaku Terjemahan','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Batas Terjemahan: mengontrol peran pengguna mana yang dapat memicu terjemahan AI, dan menetapkan anggaran token bulanan. Melebihi anggaran akan menangguhkan panggilan AI sampai bulan berikutnya.','Translation Memory'=>'Memori Terjemahan','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Memori Terjemahan menyimpan hasil AI berdasarkan hash konten, pasangan bahasa, penyedia, dan model. Mengedit sebuah postingan akan membatalkan cache sehingga panggilan terjemahan berikutnya mendapatkan hasil yang baru.','Translation Memory cleared. %d cached block was removed.'=>'Memori Terjemahan dibersihkan. %d blok yang di-cache dihapus.' . "\0" . '','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Memori Terjemahan: menyimpan seluruh postingan yang telah diterjemahkan berdasarkan hash konten. Bersihkan jika Anda ingin memaksa terjemahan ulang semua postingan tanpa mempedulikan apakah kontennya berubah.','Translation workflow'=>'Alur kerja terjemahan','Translation, Content Generator'=>'Terjemahan, Pembuat Konten','Treat H2 as H1 equivalent'=>'Perlakukan H2 sebagai setara H1','Type'=>'Jenis','Uli Hake'=>'Uli Hake','Uninstall %s'=>'Hapus instalasi %s','Uninstall Behaviour'=>'Penghapusan Perilaku','Uninstall setting saved.'=>'Pengaturan penghapusan disimpan.','unknown error'=>'kesalahan tidak diketahui','Unknown provider.'=>'Penyedia tidak dikenal.','Unknown search engine.'=>'Mesin pencari tidak dikenal.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'Berbeda dengan hreflang — di mana LF selalu menggantikan plugin lain karena mereka tidak dapat mengetahui konfigurasi multibahasa Anda — Open Graph berbeda: Yoast, Rank Math, dan plugin serupa sudah mengeluarkan tag OG yang benar untuk konten Anda. Menggandakan mereka tidak menambah nilai. Dalam mode otomatis, LF mendeteksi plugin SEO aktif dan menambahkan hanya apa yang tidak dapat mereka sediakan: og:locale (bahasa saat ini) dan og:locale:alternate (semua bahasa lain yang dikonfigurasi).','Up'=>'Atas','Upload .mo file'=>'Unggah file .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Unggah file .mo yang dikompilasi untuk menimpa string plugin pihak ketiga untuk lokal tertentu — misalnya, terjemahan VikBooking khusus yang menggunakan "apartemen" alih-alih "kamar". File harus mengikuti konvensi penamaan WordPress: {textdomain}-{locale}.mo (misalnya vikbooking-ca.mo). Mereka disimpan di folder unggahan dan tetap ada setelah pembaruan plugin.','Upload Override'=>'Unggah Penimpa','URL could not be mapped to a post — check the link target exists'=>'URL tidak dapat dipetakan ke posting — periksa apakah target tautan ada','URL structure'=>'Struktur URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Struktur URL: mode awalan jalur (example.com/de/) tidak memerlukan perubahan server. Mode subdomain (de.example.com) memerlukan catatan DNS wildcard, sertifikat SSL wildcard, dan perubahan konfigurasi server web — lihat panduan Pengaturan Server.','URL to enter'=>'URL yang dimasukkan','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Gunakan berbagi native saat tersedia; kembali ke salinan clipboard. Default yang disarankan untuk tombol "Bagikan".','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Gunakan tab di bagian atas halaman ini untuk mengonfigurasi setiap area. Perubahan pada tab Router berlaku segera; perubahan pada kunci AI dan pengaturan model berlaku untuk permintaan AI berikutnya.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Tabel terminologi yang dikelola pengguna per pasangan bahasa. Entri ditambahkan ke prompt sistem terjemahan agar AI menggunakan istilah yang disukai secara konsisten — penting untuk kosakata domain ("kWp", "PPA", "titik interkoneksi"), nama merek yang tidak boleh diterjemahkan, dan frasa regulasi yang distandarisasi. Kedua bidang bahasa bersifat opsional: tinggalkan "Bahasa sumber" kosong untuk menerapkan entri tanpa memandang bahasa asal; tinggalkan "Bahasa target" kosong untuk menerapkannya ke semua bahasa target sekaligus.','Using custom meta description.'=>'Menggunakan meta deskripsi khusus.','Using LF AI meta description.'=>'Menggunakan meta deskripsi AI LF.','Value source'=>'Sumber nilai','View'=>'Lihat','View built-in default'=>'Lihat default bawaan','View current robots.txt'=>'Lihat robots.txt saat ini','View details'=>'Lihat detail','View Lingua Forge details'=>'Lihat detail Lingua Forge','Visit plugin site'=>'Kunjungi situs plugin','Warning:'=>'Peringatan:','WebSite'=>'Situs Web','WebSite — front page / blog index'=>'Situs Web — halaman depan / indeks blog','What LF provides — and collision avoidance'=>'Apa yang disediakan LF — dan penghindaran tabrakan','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'Apa yang disediakan LF: tag hreflang untuk setiap bahasa yang dikonfigurasi, tag Open Graph dan Twitter Card dengan og:locale dan og:locale:alternate, Schema.org JSON-LD dengan anotasi inLanguage, dan peta situs multibahasa khusus di /lf-sitemap.xml dengan entri xhtml:link alternate untuk semua grup terjemahan.','When another SEO plugin is installed'=>'Saat plugin SEO lain terpasang','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Ketika pencatatan debug diaktifkan (melalui toggle di bawah atau dengan mendefinisikan LINGUAFORGE_AI_DEBUG di wp-config.php), fitur terjemahan dan template FSE menulis prompt AI mentah dan responsnya ke disk untuk pemecahan masalah. Gunakan bagian ini untuk memantau output tersebut dan bersihkan setelah Anda mendapatkan apa yang Anda butuhkan — file dapat tumbuh dengan cepat di halaman besar. Konfigurasikan direktori tujuan melalui filter linguaforge_debug_dir.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Jika diaktifkan, pengunjung pertama kali yang tidak memiliki cookie bahasa dan tidak memiliki prefix bahasa di URL akan dialihkan ke versi bahasa yang paling cocok. Pengalihan dilewati jika bahasa yang dipilih browser tidak termasuk dalam bahasa router aktif. Setelah pengunjung memilih bahasa melalui switcher, cookie menjadi prioritas dan header browser diabaikan pada kunjungan berikutnya.','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Saat diaktifkan, plugin mu Lingua Forge menghasilkan tag meta tambahan berikut di halaman produk: og:type=product, og:price:amount, og:price:currency, og:availability, dan setara namespace product yang digunakan oleh Facebook Catalog.','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Saat diaktifkan, URL peta situs diumumkan secara otomatis di robots.txt dan cache diperbarui saat konten yang diterjemahkan disimpan.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Saat Yoast SEO, Rank Math, All in One SEO, atau SEOPress aktif, Lingua Forge secara otomatis menekan output hreflang mereka melalui filter. Plugin SEO umum menghasilkan hreflang berdasarkan struktur URL satu bahasa dan tidak dapat memperhitungkan konfigurasi routing multibahasa Anda; output LF selalu benar.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Tingkat model mana yang digunakan untuk terjemahan halaman penuh. Kualitas menggunakan model yang dikonfigurasi dalam tabel Model di atas dan disarankan untuk terjemahan yang akurat dan panjang. Beralih ke Ringan hanya jika kecepatan atau biaya adalah prioritas dan kontennya singkat.','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Saat aktif, plugin mu mengelola set OG dasar dan LF hanya mengeluarkan tag locale (mode otomatis). Menghapusnya akan mengalihkan LF ke mode OG penuh secara otomatis.','WooCommerce'=>'WooCommerce','WooCommerce product price'=>'Harga produk WooCommerce','WooCommerce SEO settings saved.'=>'Pengaturan SEO WooCommerce disimpan.','WooCommerce store currency'=>'mata uang toko WooCommerce','Word count'=>'Jumlah kata','WP core canonical active (hreflang disabled)'=>'Canonical inti WP aktif (hreflang dinonaktifkan)','WP-CLI reference'=>'Referensi WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'Tulis prompt AI dan respons ke disk untuk pemecahan masalah','XML Sitemap'=>'Peta Situs XML','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Anda juga dapat mendefinisikan kunci sebagai konstanta atau variabel lingkungan (misalnya di wp-config.php). Sumber-sumber tersebut digunakan secara otomatis sebagai cadangan jika tidak ada kunci database yang disimpan.','You do not have permission to manage these settings.'=>'Anda tidak memiliki izin untuk mengelola pengaturan ini.','You do not have permission to read this post.'=>'Anda tidak memiliki izin untuk membaca posting ini.','{n} stale path(s)'=>'{n} jalur usang','~%d min read'=>'~%d menit baca' . "\0" . '','— Any source language —'=>'— Sumber apa saja —','— Any target language —'=>'— Bahasa target apa saja —','— Any target —'=>'— Target apa saja —','— Any —'=>'— Apa saja —','— auto-detect —'=>'— deteksi otomatis —','— Deferred to plugin'=>'— Ditangguhkan ke plugin','— Disabled'=>'— Dinonaktifkan','— Not detected'=>'— Tidak terdeteksi','— select a language —'=>'— pilih bahasa —','— toggle in Settings → Behavior.'=>'— toggle di Pengaturan → Perilaku.','← Back'=>'← Kembali','↑ Detected from current post'=>'↑ Terdeteksi dari posting saat ini','→ Locale tags only (manual setting)'=>'→ Tag lokal saja (pengaturan manual)','→ Locale tags only — deferring base OG to plugin'=>'→ Tag lokal saja — menangguhkan OG dasar ke plugin','↺ Re-translate'=>'↺ Terjemahkan ulang','↺ Refine'=>'↺ Perbaiki','↺ Refresh'=>'↺ Segarkan','↺ Refresh AI Analysis'=>'↺ Segarkan Analisis AI','↺ Refreshing…'=>'↺ Memuat ulang…','⚠ Borderline'=>'⚠ Batas','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Tidak ditemukan posting <strong>{lang}</strong>. Pastikan semua posting yang diterjemahkan memiliki meta Bahasa yang diatur ke <strong>{lang}</strong> di kotak meta Bahasa.','⚠ No changes'=>'⚠ Tidak ada perubahan','⚠ No changes — re-scan?'=>'⚠ Tidak ada perubahan — pemindaian ulang?','✅ Fixed ({n})'=>'✅ Diperbaiki ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Tidak ditemukan tautan rusak atau ketidakcocokan template untuk <strong>{lang}</strong>. Memindai <strong>{scanned}</strong> posting dan halaman — semua pemeriksaan lolos. Tautan bagian template (header, footer, sidebar) tidak termasuk di sini — gunakan tombol Perbaiki Bagian Template untuk memeriksa secara terpisah.','✅ Template fixed'=>'✅ Template diperbaiki','✓ %s notified successfully.'=>'✓ %s berhasil diberitahu.','✓ Active'=>'✓ Aktif','✓ Active at /lf-sitemap.xml'=>'✓ Aktif di /lf-sitemap.xml','✓ Active — %d URL entry with language alternates'=>'✓ Aktif — %d entri URL dengan alternatif bahasa' . "\0" . '','✓ Active — full OG + Twitter Cards'=>'✓ Aktif — OG lengkap + Twitter Cards','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Aktif — tag lokal hanya (og:locale, og:locale:alternate)','✓ All parts created.'=>'✓ Semua bagian dibuat.','✓ All templates created.'=>'✓ Semua template dibuat.','✓ All translated.'=>'✓ Semuanya diterjemahkan.','✓ Configured'=>'✓ Dikonfigurasi','✓ Connection OK'=>'✓ Koneksi OK','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Konten telah dibuat — lihat lapisan untuk meninjau, menyempurnakan, dan menerapkan.','✓ Done'=>'✓ Selesai','✓ Enabled'=>'✓ Diaktifkan','✓ Good length'=>'✓ Panjang yang baik','✓ Hreflang active'=>'✓ Hreflang aktif','✓ In safe storage'=>'✓ Disimpan di penyimpanan aman','✓ Language installed.'=>'✓ Bahasa terinstal.','✓ LF outputs'=>'✓ Output LF','✓ LF outputs Article / WebPage / WebSite'=>'✓ Output LF Artikel / WebPage / WebSite','✓ LF outputs full OG + Twitter Cards'=>'✓ Output LF lengkap OG + Twitter Cards','✓ LF outputs — plugin hreflang suppressed'=>'✓ Output LF — plugin hreflang ditekan','✓ Links fixed.'=>'✓ Tautan diperbaiki.','✓ Nav refs fixed.'=>'✓ Referensi navigasi diperbaiki.','✓ Parts fixed.'=>'✓ Bagian diperbaiki.','✓ Pattern translated.'=>'✓ Pola diterjemahkan.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ robots.txt fisik ditemukan. Direktif Peta Situs LF ada.','✓ Refined — review the updated draft above.'=>'✓ Diperbaiki — tinjau draf yang diperbarui di atas.','✓ Translation saved'=>'✓ Terjemahan disimpan','✓ WP core canonical removed'=>'✓ Kanonik inti WP dihapus','✗ %s ping failed. The sitemap URL is still announced in robots.txt — the search engine will discover it on its next crawl.'=>'✗ Pinging %s gagal. URL peta situs masih diumumkan di robots.txt — mesin pencari akan menemukannya saat crawling berikutnya.','✗ Disabled'=>'✗ Dinonaktifkan','✗ Error:'=>'✗ Kesalahan:','✗ Failed:'=>'✗ Gagal:','✗ Not configured'=>'✗ Tidak dikonfigurasi','✗ Too long'=>'✗ Terlalu panjang','✗ Too short'=>'✗ Terlalu pendek','❌ Failed'=>'❌ Gagal','📄 Wrong template'=>'📄 Template yang salah','📍 Stale path (page moved)'=>'📍 Jalur usang (halaman dipindahkan)']];
